WITH RECURSIVE org AS (
  SELECT id, name, parent_id, 0 AS depth FROM departments WHERE parent_id IS NULL
  UNION ALL
  SELECT d.id, d.name, d.parent_id, org.depth + 1
  FROM departments d JOIN org ON d.parent_id = org.id
) SELECT * FROM org ORDER BY depth, id;

WITH RECURSIVE descendants AS (
  SELECT id, parent_id, id AS root_id FROM departments
  UNION ALL
  SELECT d.id, d.parent_id, descendants.root_id
  FROM departments d JOIN descendants ON d.parent_id = descendants.id
) SELECT root_id, COUNT(*) - 1 AS descendant_count FROM descendants GROUP BY root_id;

